#!/usr/bin/env python3
from pathlib import Path
import os

PROJECT=Path(os.environ.get("MINI4X_PROJECT","project"))
view=PROJECT/"app/src/main/java/com/example/mini4x/ui/Mini4xView.kt"
s=view.read_text()
assert "drawTechDetailLandscape(c:Canvas)" not in s,"landscape overlay patch already applied"

routes={
    "    private fun drawTechDetail(c:Canvas){":"drawTechDetailLandscape",
    "    private fun drawUnitInfo(c:Canvas){":"drawUnitInfoLandscape",
    "    private fun drawCityInfo(c:Canvas){":"drawCityInfoLandscape",
    "    private fun drawDiplomacy(c:Canvas){":"drawDiplomacyLandscape",
    "    private fun drawStats(c:Canvas){":"drawStatsLandscape",
    "    private fun drawHelp(c:Canvas){":"drawHelpLandscape",
}
for sig,helper in routes.items():
    assert s.count(sig)==1,f"landscape route anchor drifted: {sig}"
    s=s.replace(sig,sig+"\n        if(height<=width){"+helper+"(c);return}",1)

helpers='    private fun drawTechDetailLandscape(c:Canvas){\n        val id=selectedTechId?:run{presenter.setScreen(ScreenMode.TECH);return}\n        val tech=TechnologyCatalog[id];val owned=id in presenter.state.players[0].technologies\n        val cost=TechnologyCatalog.researchCost(presenter.state,0,id);val legal=TechnologyCatalog.canResearch(presenter.state,0,id);val affordable=presenter.state.players[0].stars>=cost\n        drawTech(c);drawOverlayTopBar(c,"")\n        val r=modalPanel(c,height*.12f,height*.91f,.70f);val cx=r.centerX()\n        val icon=RectF(r.left+22*d,r.top+24*d,r.left+72*d,r.top+74*d)\n        paint.color=Color.rgb(14,39,55);c.drawCircle(icon.centerX(),icon.centerY(),29*d,paint)\n        paint.style=Paint.Style.STROKE;paint.strokeWidth=1.7f*d;paint.color=when{owned->Color.rgb(48,200,98);legal&&affordable->Color.rgb(48,161,226);else->Color.rgb(96,111,121)};c.drawCircle(icon.centerX(),icon.centerY(),29*d,paint);paint.style=Paint.Style.FILL\n        uiBitmap(c,"tech/${tech.id}.png",icon)\n        text.textAlign=Paint.Align.LEFT;text.typeface=Typeface.DEFAULT_BOLD;text.textSize=16*d;text.color=Color.WHITE;c.drawText(tech.label,r.left+88*d,r.top+39*d,text)\n        val stateText=when{owned->"COMPLETED";!legal->"PREREQUISITE REQUIRED";!affordable->"NEED ${cost-presenter.state.players[0].stars} MORE STARS";else->"AVAILABLE TO RESEARCH"}\n        val stateColor=when{owned->Color.rgb(58,208,108);legal&&affordable->Color.rgb(77,186,238);else->Color.rgb(154,163,170)}\n        text.textSize=7.6f*d;text.color=stateColor;c.drawText(stateText,r.left+88*d,r.top+59*d,text)\n        drawStar(c,r.left+94*d,r.top+79*d,4.5f*d,Color.rgb(247,194,45));text.textSize=9*d;text.color=Color.WHITE;c.drawText("$cost",r.left+108*d,r.top+82*d,text)\n        val desc=RectF(r.left+18*d,r.top+104*d,r.right-18*d,r.bottom-57*d);paint.color=Color.rgb(10,22,30);c.drawRoundRect(desc,10*d,10*d,paint)\n        text.textAlign=Paint.Align.CENTER;text.typeface=Typeface.DEFAULT_BOLD;text.textSize=8*d;text.color=Color.rgb(174,199,213);c.drawText("UNLOCKS / EFFECT",cx,desc.top+20*d,text)\n        text.typeface=Typeface.DEFAULT;text.textAlign=Paint.Align.LEFT;text.textSize=8.5f*d;text.color=Color.rgb(229,235,238);wrapText(c,tech.effect,desc.left+16*d,desc.top+42*d,desc.width()-32*d,17*d)\n        text.textAlign=Paint.Align.CENTER\n        tech.requires?.let{req->val reqTech=TechnologyCatalog[req];val iy=desc.bottom-20*d;text.textSize=7*d;text.color=Color.rgb(142,162,173);c.drawText("REQUIRES",cx-48*d,iy+2*d,text);uiBitmap(c,"tech/${req}.png",RectF(cx-11*d,iy-14*d,cx+11*d,iy+8*d));text.textSize=7.5f*d;text.color=Color.WHITE;c.drawText(reqTech.label,cx+48*d,iy+2*d,text)}\n        val by=r.bottom-44*d;modalSecondaryRect=RectF(cx-94*d,by,cx-8*d,by+32*d);paint.color=Color.rgb(28,72,99);c.drawRoundRect(modalSecondaryRect!!,9*d,9*d,paint);text.textSize=9.5f*d;text.color=Color.WHITE;c.drawText("BACK",modalSecondaryRect!!.centerX(),modalSecondaryRect!!.centerY()+3.5f*d,text)\n        modalPrimaryRect=null\n        if(!owned&&legal){modalPrimaryRect=RectF(cx+8*d,by,cx+102*d,by+32*d);paint.color=if(affordable)Color.rgb(35,183,81) else Color.rgb(74,85,92);c.drawRoundRect(modalPrimaryRect!!,9*d,9*d,paint);text.color=Color.WHITE;c.drawText("RESEARCH",modalPrimaryRect!!.centerX(),modalPrimaryRect!!.centerY()+3.5f*d,text)}\n    }\n\n    private fun drawUnitInfoLandscape(c:Canvas){\n        val u=presenter.selection.unitId?.let(presenter.state::unit)?:run{presenter.setScreen(ScreenMode.WORLD);return};val def=UnitCatalog[u.kind];val skills=UnitCatalog.skills(u).toList()\n        drawOverlayTopBar(c,"");val r=modalPanel(c,height*.11f,height*.92f,.76f);val fid=playerFactionId(u.owner);val mid=r.centerX()\n        text.textAlign=Paint.Align.LEFT;text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textSize=17*d;text.color=Color.WHITE;c.drawText(unitLabel(u.kind),r.left+20*d,r.top+34*d,text)\n        val domain=if(u.kind in setOf(UnitKind.RAFT,UnitKind.RAMMER,UnitKind.SCOUT,UnitKind.BOMBER,UnitKind.JUGGERNAUT))"Water" else "Land"\n        paint.color=Color.rgb(238,240,238);c.drawRoundRect(r.left+132*d,r.top+16*d,r.left+180*d,r.top+36*d,10*d,10*d,paint);text.textSize=7.5f*d;text.color=Color.rgb(75,80,83);c.drawText(domain,r.left+141*d,r.top+30*d,text)\n        def.cost?.let{drawStar(c,r.right-47*d,r.top+26*d,4.5f*d,Color.rgb(247,194,45));text.textAlign=Paint.Align.RIGHT;text.textSize=8.5f*d;text.color=Color.WHITE;c.drawText(it.toString(),r.right-25*d,r.top+29*d,text)}\n        val art=RectF(r.left+22*d,r.top+53*d,r.left+112*d,r.top+143*d);uiBitmap(c,"units/${fid}_${bodyKind(u.kind)}_body.png",art)\n        if(skills.isNotEmpty()){val skill=skills.first();paint.color=Color.rgb(72,76,82);c.drawRoundRect(r.left+22*d,r.top+164*d,r.left+112*d,r.top+185*d,10*d,10*d,paint);text.textAlign=Paint.Align.CENTER;text.textSize=7.5f*d;text.color=Color.rgb(225,230,232);c.drawText(skillLabel(skill).uppercase(),r.left+67*d,r.top+178*d,text);text.textAlign=Paint.Align.LEFT;text.textSize=8*d;text.color=Color.rgb(194,205,211);wrapText(c,skillDescription(skill),r.left+22*d,r.top+207*d,mid-r.left-34*d,16*d)}\n        val x1=mid+18*d;val x2=r.right-22*d;val y0=r.top+62*d\n        statRow(c,"Health","${u.hp}/${UnitCatalog.maxHP(u)}",x1,x2,y0,true);statRow(c,"Attack",formatStat(def.attack),x1,x2,y0+30*d,true);statRow(c,"Defense",formatStat(def.defense),x1,x2,y0+60*d,true);statRow(c,"Movement",def.movement.toString(),x1,x2,y0+90*d,true);statRow(c,"Range",def.range.toString(),x1,x2,y0+120*d,true)\n        modalPrimaryRect=RectF(mid-45*d,r.bottom-43*d,mid+45*d,r.bottom-11*d);paint.color=Color.rgb(15,137,210);c.drawRoundRect(modalPrimaryRect!!,9*d,9*d,paint);text.textAlign=Paint.Align.CENTER;text.textSize=10.5f*d;text.color=Color.WHITE;c.drawText("OK",modalPrimaryRect!!.centerX(),modalPrimaryRect!!.centerY()+3.5f*d,text);modalSecondaryRect=null\n    }\n\n    private fun drawCityInfoLandscape(c:Canvas){\n        val city=presenter.selection.cityId?.let(presenter.state::city)?:run{presenter.setScreen(ScreenMode.WORLD);return}\n        drawOverlayTopBar(c,"");val r=modalPanel(c,height*.11f,height*.92f,.76f);val fid=playerFactionId(city.owner);val mid=r.centerX()\n        text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textAlign=Paint.Align.LEFT;text.textSize=16*d;text.color=Color.WHITE;c.drawText("${cityName(city)} · City lvl ${city.level}",r.left+20*d,r.top+34*d,text)\n        val art=RectF(r.left+24*d,r.top+58*d,mid-30*d,r.top+183*d);uiBitmap(c,"cities/${fid}_city_l${city.level.coerceAtMost(5)}.png",art)\n        val x1=mid+18*d;val x2=r.right-22*d;val y0=r.top+57*d\n        statRow(c,"Population","${city.population}/${city.populationNeeded}",x1,x2,y0,true);statRow(c,"Income","${city.income(0)} / turn",x1,x2,y0+29*d,true);statRow(c,"Unit capacity","${city.supportedUnitIds.size}/${city.capacity}",x1,x2,y0+58*d,true);statRow(c,"Workshop",if(city.workshop)"Yes" else "No",x1,x2,y0+87*d);statRow(c,"City wall",if(city.wall)"Yes" else "No",x1,x2,y0+116*d);statRow(c,"Territory",if(city.borderExpanded)"Expanded" else "Standard",x1,x2,y0+145*d)\n        val by=r.bottom-44*d;modalSecondaryRect=RectF(mid-98*d,by,mid-8*d,by+32*d);paint.color=Color.rgb(15,137,210);c.drawRoundRect(modalSecondaryRect!!,9*d,9*d,paint);text.textAlign=Paint.Align.CENTER;text.textSize=9.5f*d;text.color=Color.WHITE;c.drawText("BACK",modalSecondaryRect!!.centerX(),modalSecondaryRect!!.centerY()+3.5f*d,text)\n        modalPrimaryRect=RectF(mid+8*d,by,mid+105*d,by+32*d);paint.color=Color.rgb(35,183,81);c.drawRoundRect(modalPrimaryRect!!,9*d,9*d,paint);c.drawText("ACTIONS",modalPrimaryRect!!.centerX(),modalPrimaryRect!!.centerY()+3.5f*d,text)\n    }\n\n    private fun drawDiplomacyLandscape(c:Canvas){\n        drawOverlayTopBar(c,"DIPLOMACY");diplomacyActionRects=emptyList();diplomacyConfirmRect=null;diplomacyCancelRect=null\n        val r=modalPanel(c,height*.10f,height*.93f,.86f);val state=presenter.state;val player=state.players[0]\n        val rivals=state.players.indices.filter{it!=0&&!state.players[it].eliminated}\n        text.textAlign=Paint.Align.LEFT;text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textSize=7.8f*d;text.color=Color.rgb(183,201,211);c.drawText("Treaties and embassies use normal game rules and costs.",r.left+16*d,r.top+27*d,text)\n        val pairs=mutableListOf<Pair<RectF,Command>>();val gap=9*d;val count=max(1,rivals.size);val cardW=(r.width()-24*d-gap*(count-1))/count;val cardTop=r.top+45*d;val cardBottom=r.bottom-14*d\n        rivals.forEachIndexed{i,pid->\n            val left=r.left+12*d+i*(cardW+gap);val card=RectF(left,cardTop,left+cardW,cardBottom);paint.color=Color.rgb(9,20,27);c.drawRoundRect(card,10*d,10*d,paint);paint.style=Paint.Style.STROKE;paint.strokeWidth=1f*d;paint.color=Color.rgb(47,66,77);c.drawRoundRect(card,10*d,10*d,paint);paint.style=Paint.Style.FILL\n            paint.color=playerFactionColor(pid);c.drawCircle(card.left+18*d,card.top+22*d,8*d,paint);drawCrown(c,card.left+18*d,card.top+22*d,4.5f*d,Color.WHITE)\n            text.textAlign=Paint.Align.LEFT;text.typeface=Typeface.DEFAULT_BOLD;text.textSize=9*d;text.color=Color.WHITE;c.drawText(playerFactionName(pid),card.left+32*d,card.top+25*d,text)\n            val relation=state.diplomacy[0][pid].name.lowercase().replaceFirstChar{it.uppercase()};val met=pid in player.metPlayers;val embassy=pid in player.embassies\n            text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textSize=6.4f*d;text.color=Color.rgb(174,194,205);c.drawText("$relation · ${if(met)"Met" else "Not met"} · ${if(embassy)"Embassy active" else "No embassy"}",card.left+12*d,card.top+48*d,text)\n            val inside=state.ownedUnits(0).count{u->state.tile(u.pos)?.territoryOwner==pid}\n            if(state.diplomacy[0][pid]==Relation.PEACE&&inside>0){text.textSize=6.3f*d;text.color=Color.rgb(244,148,126);wrapText(c,"Warning: breaking peace loses $inside unit${if(inside==1)"" else "s"} inside their territory.",card.left+12*d,card.top+72*d,card.width()-24*d,14*d)}\n            val candidates=listOf<Command>(EstablishEmbassy(0,pid),OfferPeace(0,pid),BreakPeace(0,pid));val legal=candidates.filter{CommandEngine.validate(state,it)==null};val bGap=5*d;val buttonY=card.bottom-38*d\n            if(legal.isEmpty()){\n                val hint=when{"strategy" !in player.technologies&&"diplomacy" !in player.technologies->"Research Strategy for peace · Diplomacy for embassies";"strategy" !in player.technologies->"Research Strategy to negotiate peace";"diplomacy" !in player.technologies&&!embassy->"Research Diplomacy to establish embassies";else->"No diplomatic action is currently available"}\n                text.textSize=6.2f*d;text.color=Color.rgb(134,153,164);wrapText(c,hint,card.left+12*d,card.bottom-26*d,card.width()-24*d,13*d)\n            }else{\n                val bw=(card.width()-24*d-bGap*(legal.size-1))/legal.size\n                legal.forEachIndexed{j,cmd->val bx=card.left+12*d+j*(bw+bGap);val br=RectF(bx,buttonY,bx+bw,buttonY+29*d);paint.color=if(cmd is BreakPeace)Color.rgb(126,54,47) else Color.rgb(26,125,190);c.drawRoundRect(br,8*d,8*d,paint);val label=when(cmd){is EstablishEmbassy->"EMBASSY";is OfferPeace->"PEACE";is BreakPeace->"BREAK";else->commandLabel(cmd).uppercase()};text.textAlign=Paint.Align.CENTER;text.typeface=Typeface.DEFAULT_BOLD;text.textSize=6.1f*d;text.color=Color.WHITE;c.drawText(label,br.centerX(),br.centerY()+2.5f*d,text);pairs+=br to cmd}\n            }\n        }\n        text.textAlign=Paint.Align.CENTER;diplomacyActionRects=pairs\n        diplomacyConfirmBreak?.let{cmd->\n            diplomacyActionRects=emptyList();paint.color=Color.argb(185,0,0,0);c.drawRect(0f,0f,width.toFloat(),height.toFloat(),paint)\n            val q=modalPanel(c,height*.18f,height*.82f,.58f);val target=cmd.targetPlayerId;val inside=state.ownedUnits(0).count{u->state.tile(u.pos)?.territoryOwner==target}\n            text.typeface=Typeface.DEFAULT_BOLD;text.textSize=15*d;text.color=Color.WHITE;c.drawText("BREAK PEACE?",q.centerX(),q.top+34*d,text);text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textSize=8*d;text.color=Color.rgb(216,224,228);c.drawText("Declare war on ${playerFactionName(target)}.",q.centerX(),q.top+66*d,text)\n            if(inside>0){text.color=Color.rgb(247,154,132);c.drawText("$inside unit${if(inside==1)"" else "s"} in their territory will be lost.",q.centerX(),q.top+92*d,text)}\n            text.color=Color.rgb(216,224,228);c.drawText("Your remaining units cannot act this turn.",q.centerX(),q.top+118*d,text);val by=q.bottom-43*d\n            diplomacyCancelRect=RectF(q.centerX()-102*d,by,q.centerX()-8*d,by+32*d);paint.color=Color.rgb(43,68,82);c.drawRoundRect(diplomacyCancelRect!!,9*d,9*d,paint);diplomacyConfirmRect=RectF(q.centerX()+8*d,by,q.centerX()+102*d,by+32*d);paint.color=Color.rgb(137,53,45);c.drawRoundRect(diplomacyConfirmRect!!,9*d,9*d,paint);text.typeface=Typeface.DEFAULT_BOLD;text.textSize=7.7f*d;text.color=Color.WHITE;c.drawText("CANCEL",diplomacyCancelRect!!.centerX(),diplomacyCancelRect!!.centerY()+3*d,text);c.drawText("BREAK PEACE",diplomacyConfirmRect!!.centerX(),diplomacyConfirmRect!!.centerY()+3*d,text)\n        }\n    }\n\n    private fun drawStatsLandscape(c:Canvas){\n        drawOverlayTopBar(c,"GAME STATS");val r=modalPanel(c,height*.10f,height*.92f,.82f);val state=presenter.state;val rankings=state.players.indices.sortedByDescending{state.score[it]};val mid=r.centerX()\n        text.typeface=Typeface.DEFAULT_BOLD;text.textSize=9*d;text.color=Color.rgb(163,184,196);text.textAlign=Paint.Align.LEFT;c.drawText("RANKING",r.left+18*d,r.top+28*d,text);c.drawText("YOUR EMPIRE",mid+18*d,r.top+28*d,text)\n        var y=r.top+57*d\n        for((rank,pid) in rankings.withIndex()){val row=RectF(r.left+12*d,y-18*d,mid-12*d,y+18*d);paint.color=if(pid==0)Color.rgb(17,39,52) else Color.rgb(10,19,25);c.drawRoundRect(row,8*d,8*d,paint);paint.color=playerFactionColor(pid);c.drawCircle(row.left+18*d,y,7*d,paint);text.textAlign=Paint.Align.LEFT;text.typeface=Typeface.DEFAULT_BOLD;text.textSize=8*d;text.color=Color.WHITE;c.drawText("${rank+1}. ${playerFactionName(pid)}",row.left+32*d,y+3*d,text);text.textAlign=Paint.Align.RIGHT;c.drawText("${state.score[pid]}  ★${state.players[pid].stars}",row.right-10*d,y+3*d,text);y+=43*d}\n        val pid=0;val territory=(0 until state.size).sumOf{x->(0 until state.size).count{yy->state.map[x][yy].territoryOwner==pid}};val x1=mid+18*d;val x2=r.right-20*d;val sy=r.top+57*d\n        statRow(c,"Cities",state.ownedCities(pid).size.toString(),x1,x2,sy,true);statRow(c,"Units",state.ownedUnits(pid).size.toString(),x1,x2,sy+30*d,true);statRow(c,"Technologies",state.players[pid].technologies.size.toString(),x1,x2,sy+60*d,true);statRow(c,"Territory","$territory tiles",x1,x2,sy+90*d,true);statRow(c,"Explored","${state.discoveredTiles[pid].size} tiles",x1,x2,sy+120*d,true);statRow(c,"Kills / losses","${state.players[pid].kills} / ${state.players[pid].losses}",x1,x2,sy+150*d,true)\n        modalPrimaryRect=RectF(mid-45*d,r.bottom-43*d,mid+45*d,r.bottom-11*d);paint.color=Color.rgb(15,137,210);c.drawRoundRect(modalPrimaryRect!!,9*d,9*d,paint);text.textAlign=Paint.Align.CENTER;text.textSize=10*d;text.color=Color.WHITE;c.drawText("BACK",modalPrimaryRect!!.centerX(),modalPrimaryRect!!.centerY()+3.5f*d,text);modalSecondaryRect=null\n    }\n\n    private fun drawHelpLandscape(c:Canvas){\n        if(helpReturn==ScreenMode.TITLE)circleButton(c,34*d,42*d,21*d,"‹","") else drawOverlayTopBar(c,"")\n        val r=modalPanel(c,height*.09f,height*.93f,.84f);text.typeface=Typeface.DEFAULT_BOLD;text.textSize=17*d;text.color=Color.WHITE;text.textAlign=Paint.Align.CENTER;c.drawText("HOW TO PLAY",width/2f,r.top+34*d,text)\n        val lines=listOf("1. Tap a unit, then a highlighted tile to move.","2. Explored terrain stays revealed permanently.","3. Capture villages one turn after occupying them.","4. Develop cities for income and unit capacity.","5. Research technologies to unlock terrain, units and economy.","6. Use terrain, roads and zone-of-control to position armies.","7. Win by the selected game mode\'s objective.","Pinch to zoom · drag to pan · double-tap the map to recenter.")\n        val gap=18*d;val colW=(r.width()-54*d)/2;val x0=r.left+20*d;val x1=x0+colW+gap;text.typeface=Typeface.create("sans-serif",Typeface.NORMAL);text.textSize=8.2f*d;text.color=Color.rgb(220,228,232);text.textAlign=Paint.Align.LEFT\n        for(i in lines.indices){val col=if(i<4)0 else 1;val row=if(i<4)i else i-4;val x=if(col==0)x0 else x1;val y=r.top+(72+row*54)*d;wrapText(c,lines[i],x,y,colW,16*d)}\n        text.textAlign=Paint.Align.CENTER;modalPrimaryRect=RectF(r.centerX()-47*d,r.bottom-43*d,r.centerX()+47*d,r.bottom-11*d);paint.color=Color.rgb(15,137,210);c.drawRoundRect(modalPrimaryRect!!,9*d,9*d,paint);text.textSize=10*d;text.color=Color.WHITE;c.drawText("BACK",modalPrimaryRect!!.centerX(),modalPrimaryRect!!.centerY()+3.5f*d,text);modalSecondaryRect=null\n    }\n'
